 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry } = THREE;

  const group = new Group();

  const atlasW = 512;
  const atlasH = 320;
  const aspect = atlasW / atlasH;
  const planeW = 4.0;
  const planeH = planeW / aspect;

  const geometry = new PlaneGeometry(planeW, planeH);
  const material = new MeshBasicNodeMaterial();
  const surface = new Mesh(geometry, material);

  group.add(surface);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = items.find((item) => item.role === 'headline') ?? items[0];
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const paper = colors.paper ?? '#e8ecf2';

  if (headline && headline.text) {
    const title = ctx.fontAtlas.createText(headline.text, {
      fontSize: headline.typography?.fontSize ?? 96,
      color: paper,
      align: 'center'
    });
    title.position.z = 0.05;
    group.add(title);
  }

  let mainTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      mainTexture = tex;
      material.colorNode = texture(mainTexture, uv());
      material.needsUpdate = true;
    });
  }

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (mainTexture) mainTexture.dispose();
  };

  return group;
}
